import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as t,o as n,j as i,G as r,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Fairness for Servicemembers and their Families Act of 2025","description":"","frontmatter":{"legisId":"2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025","title":"Fairness for Servicemembers and their Families Act of 2025","displayTitle":"Fairness for Servicemembers and their Families Act of 2025","lawNumber":"119-54","billNumber":"H.R. 970","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ54.xml","publishDate":"2025-12-12T00:00:00-05:00","industries":["defense","finance","government-operations"],"agencies":["Department of Veterans Affairs","Bureau of Labor Statistics"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Fairness for Servicemembers and their Families Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Fairness for Servicemembers and their Families Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025\\",\\"datePublished\\":\\"2025-12-12T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025.md","filePath":"congress-bills/2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025.md","lastUpdated":1788887623000}'),m={name:"congress-bills/2025-12-12-fairness-for-servicemembers-and-their-families-act-of-2025.md"},b=Object.assign(m,{setup(c){return(f,e)=>(n(),t("div",null,[e[0]||(e[0]=i("h1",{id:"fairness-for-servicemembers-and-their-families-act-of-2025",tabindex:"-1"},[l("Fairness for Servicemembers and their Families Act of 2025 "),i("a",{class:"header-anchor",href:"#fairness-for-servicemembers-and-their-families-act-of-2025","aria-label":'Permalink to "Fairness for Servicemembers and their Families Act of 2025"'},"​")],-1)),r(a),r(s,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Friday, December 12, 2025. Public Law 119-54, H.R. 970.</p><p><strong>Headline:</strong> The law requires recurring inflation reviews of automatic life insurance coverage for servicemembers and veterans.</p><p><strong>Why it matters:</strong> The reviews will show whether the current $500,000 maximum coverage under two federal insurance programs has kept pace with inflation and may guide future increases.</p><p><strong>What the law does:</strong></p><ul><li>Requires the Secretary of Veterans Affairs to conduct the first review by January 1, 2026, and repeat it every five years.</li><li>Compares current maximum coverage with a benchmark based on the average five-year change in the Consumer Price Index for all urban consumers.</li><li>Requires review results to be reported to the House and Senate Veterans’ Affairs Committees.</li><li>Allows the findings to guide future increases using the programs’ existing coverage increments.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Servicemembers covered by Servicemembers’ Group Life Insurance.</li><li>Veterans covered by Veterans’ Group Life Insurance.</li><li>Families and beneficiaries who rely on those policies.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Covered servicemembers and veterans may see future maximum coverage increases if reviews show inflation has reduced its value.</li><li>Policyholders receive no automatic increase solely from the review requirement.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="fairness-for-servicemembers-and-their-families-act-of-2025-1" tabindex="-1">Fairness for Servicemembers and their Families Act of 2025 <a class="header-anchor" href="#fairness-for-servicemembers-and-their-families-act-of-2025-1" aria-label="Permalink to &quot;Fairness for Servicemembers and their Families Act of 2025&quot;">​</a></h3><p>This law requires the Secretary of Veterans Affairs to review the maximum automatic life insurance coverage available under the Servicemembers’ Group Life Insurance and Veterans’ Group Life Insurance programs. Beginning January 1, 2026, the review must occur every five years and compare the current coverage amount with an inflation-based benchmark.</p><p><strong>Key takeaways:</strong></p><ul><li>The first review is due January 1, 2026, with additional reviews required every five years.</li><li>The inflation-based benchmark is calculated by multiplying $500,000 by the average percentage change in the Consumer Price Index over the preceding five fiscal years.</li><li>The Consumer Price Index used is the index for all urban consumers published by the Bureau of Labor Statistics.</li><li>The Secretary must report each review’s results to the House and Senate Veterans’ Affairs Committees.</li><li>The review results may guide future coverage increases within the programs’ existing administrative increment structure.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ54.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ54.xml</a></p>',15))]))}});export{p as __pageData,b as default};
